const { Resvg } = require("@resvg/resvg-js");
const fs = require("fs");
const path = require("path");

const dir = __dirname;
const targets = [
  "hosting-free-month-1080x1350.svg",
  "hosting-free-month-1080x1080.svg",
];
for (const f of targets) {
  const svg = fs.readFileSync(path.join(dir, f), "utf8");
  const r = new Resvg(svg, {
    font: { loadSystemFonts: true, defaultFontFamily: "Liberation Sans" },
    shapeRendering: 2,
    textRendering: 2,
  });
  const png = r.render().asPng();
  const out = f.replace(/\.svg$/, ".png");
  fs.writeFileSync(path.join(dir, out), png);
  console.log(out, `${(png.length / 1024).toFixed(0)}kb`);
}
